    ITEM_SEQ = #{itemSeq}
    , MEDICINE_CATEGORY = #{medicineCategory}
    , MANUFACTURER = #{manufacturer}
    , SPECIFICATION = #{specification}
    , INGREDIENT = #{ingredient}
